// Label each downloaded image with its platform filename, then merge ALL images
// into ONE item: the Compression node runs once per item, so 4 items would
// produce 4 zips. One item with 4 binaries produces the single zip we want.
const files = [];
const binary = {};
$input.all().forEach((item, i) => {
  // itemMatching follows n8n's item pairing instead of assuming index alignment,
  // so labels stay correct even if an upstream node drops or reorders items.
  const job = $('Build platform jobs').itemMatching(i).json;
  if (!job || !job.basename) {
    throw new Error(`Could not pair downloaded image #${i} with its platform job.`);
  }
  const bin = item.binary.data;
  // The file extension follows the format Bloom actually served, not a hardcoded .png.
  const ext = (bin.fileExtension || (bin.mimeType || '').split('/')[1] || 'png').replace('jpeg', 'jpg');
  const filename = `${job.basename}.${ext}`;
  bin.fileName = filename;
  binary[job.basename] = bin;
  files.push({
    platform: job.platform,
    filename,
    aspectRatio: job.aspectRatio,
    headline: job.headline,
    caption: job.caption,
  });
});
return [{ json: { files }, binary }];

